/**
 * Called when a membership ends or a workspace is deleted. Every session that
 * defaults to `orgId` (for `userId` only, when given) moves to another
 * workspace its user still belongs to, or to none. Other sessions and other
 * workspaces are left alone.
 */
export async function detachSessionsFromOrg(
  orgId: OrgId,
  userId: UserId | null = null,
): Promise<void> {
  const affected = await sessionRepo.listSessionsDefaultingTo(orgId, userId);

  for (const session of affected) {
    const remaining = await orgRepo.listOrgsForUser(session.userId);
    const fallback = remaining.find((org) => org.id !== orgId);
    await sessionRepo.setActiveOrg(session.id, fallback?.id ?? null);
  }
}

