 * Checks the whole batch, then writes it. Every refusal happens before the
 * first row is written, so a refused batch leaves nothing behind. `replacing`
 * is the invitation a re-send withdraws: it is treated as already gone for the
 * duplicate and seat checks, and revoked just before the new rows are written.
 */
async function issueInvitations(
  actor: Actor,
  input: InviteMembersInput,
  replacing: Invitation | null,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  const verdict = await consumeRateLimit(
    input.orgId,
    INVITE_BUCKET,
    input.invites.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const emails = input.invites.map((invite) => normalizeEmail(invite.email));
  if (new Set(emails).size !== emails.length) {
    throw new Error("The same email address appears more than once in this batch");
  }

  const now = toIsoTimestamp(new Date());
  const openEmails = new Set(
    (await invitationRepo.listPendingInvitations(input.orgId))
      .filter((row) => row.id !== replacing?.id && isOpen(row, now))
      .map((row) => normalizeEmail(row.email)),
  );

  for (const email of emails) {
    if (openEmails.has(email)) {
      throw new Error(`${email} already has a pending invitation`);
    }
    if (await memberRepo.findLiveMemberByEmail(input.orgId, email)) {
      throw new Error(`${email} is already a member of this workspace`);
    }
  }

