  // about to be withdrawn, so its seat is handed to the new row.
  const seatsUsed =
    (await memberRepo.countActiveMembers(input.orgId)) +
    (await invitationRepo.countPendingInvitations(input.orgId, now)) -
    (replacing !== null && isOpen(replacing, now) ? 1 : 0);

