import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { getDb, sessions } from "@/server/db";
import { hashToken } from "@/lib/hash";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as invitationService from "@/server/services/invitation-service";
import * as memberService from "@/server/services/member-service";
import * as notificationService from "@/server/services/notification-service";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { emit } from "@/lib/event-bus";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});
afterAll(() => cleanup());

describe("scratch verification", () => {
  it("rejoin reuses the member row, new role and inviter", async () => {
    const t = await createTenant("v-rejoin", "growth");
    const contractor = await userRepo.insertUser({ email: "Contractor@v-rejoin.test", name: "C", passwordHash: "x" });
    const inv1 = await invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: "contractor@v-rejoin.test", role: "member" });
    const raw1 = "t".repeat(32);
    // mint known token directly
    await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "contractor@v-rejoin.test", role: "member", expiresInDays: 14 }, t.userIds.admin, hashToken(raw1));
    void inv1;
    const first = await invitationService.acceptInvitation(contractor.id, { token: raw1 });
    const m1 = await memberRepo.findMember(t.org.id, contractor.id);
    expect(m1?.id).toBe(first.id);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: first.id });
    expect(await memberRepo.findMember(t.org.id, contractor.id)).toBeNull();

    const raw2 = "u".repeat(32);
    await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "contractor@v-rejoin.test", role: "viewer", expiresInDays: 14 }, t.userIds.owner, hashToken(raw2));
    const rejoined = await invitationService.acceptInvitation(contractor.id, { token: raw2 });
    expect(rejoined.id).toBe(first.id);
    expect(rejoined.role).toBe("viewer");
    expect(rejoined.invitedBy).toBe(t.userIds.owner);
    expect(rejoined.status).toBe("active");
    expect((await memberRepo.findMember(t.org.id, contractor.id))?.role).toBe("viewer");
    await expect(memberRepo.countActiveMembers(t.org.id)).resolves.toBe(5);
  });

  it("refuses duplicates, existing members, and batch dupes atomically", async () => {
    const t = await createTenant("v-dupe", "growth");
    await expect(invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: "MEMBER@v-dupe.test", role: "member" })).rejects.toThrow(/already a member/);
    await expect(invitationService.inviteMembers(t.actors.admin, { orgId: t.org.id, invites: [
      { email: "x@v-dupe.test", role: "member" }, { email: "X@v-dupe.test", role: "member" },
    ] })).rejects.toThrow(/more than once/);
    await expect(invitationRepo.countPendingInvitations(t.org.id)).resolves.toBe(0);
    await invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: "y@v-dupe.test", role: "member" });
    await expect(invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: "Y@v-dupe.test", role: "member" })).rejects.toThrow(/pending/);
    await expect(invitationRepo.countPendingInvitations(t.org.id)).resolves.toBe(1);
  });

  it("wrong email refused, revoked frees seat, expired resend keeps role", async () => {
    const t = await createTenant("v-email", "free");
    // free plan: 4 members already from createTenant -> over quota; use growth check separately
    const g = await createTenant("v-email-g", "growth");
    const raw = "w".repeat(32);
    const inv = await invitationRepo.insertInvitation(g.org.id, { orgId: g.org.id, email: "right@v-email-g.test", role: "admin", expiresInDays: 14 }, g.userIds.owner, hashToken(raw));
    const wrong = await userRepo.insertUser({ email: "wrong@v-email-g.test", name: "W", passwordHash: "x" });
    await expect(invitationService.acceptInvitation(wrong.id, { token: raw })).rejects.toThrow(/different email/);
    const right = await userRepo.insertUser({ email: "RIGHT@v-email-g.test", name: "R", passwordHash: "x" });
    const m = await invitationService.acceptInvitation(right.id, { token: raw });
    expect(m.role).toBe("admin");
    await expect(invitationService.acceptInvitation(right.id, { token: raw })).rejects.toThrow(/accepted/);
    void inv;

    // expired resend
    const raw2 = "e".repeat(32);
    const exp = await invitationRepo.insertInvitation(g.org.id, { orgId: g.org.id, email: "late@v-email-g.test", role: "viewer", expiresInDays: -1 }, g.userIds.owner, hashToken(raw2));
    const re = await invitationService.resendInvitation(g.actors.admin, exp.id);
    expect(re.role).toBe("viewer");
    expect(re.email).toBe("late@v-email-g.test");
    expect(new Date(re.expiresAt).getTime() - Date.now()).toBeGreaterThan(13 * 24 * 3600 * 1000);
    await expect(invitationRepo.findInvitationByTokenHash(hashToken(raw2))).resolves.toMatchObject({ revokedAt: expect.any(String) });
    void t;
  });

  it("notifications and digest skip removed members; session detaches", async () => {
    const t = await createTenant("v-notif", "growth");
    const target = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    if (!target) throw new Error("missing");
    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.viewer, kind: "comment_created", inApp: true, email: false, digestOnly: true });
    // session defaulting to the org
    const sessionToken = "s".repeat(40);
    await sessionRepo.createSession(t.userIds.viewer, hashToken(sessionToken), new Date(Date.now() + 86400000).toISOString() as never);
    const row = getDb().select().from(sessions).all().find((s) => s.userId === t.userIds.viewer);
    if (!row) throw new Error("no session");
    await sessionRepo.setActiveOrg(row.id as never, t.org.id);

    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: target.id });
    const after = getDb().select().from(sessions).all().find((s) => s.id === row.id);
    expect(after?.activeOrgId).toBeNull();

    await expect(preferenceRepo.listDigestSubscribers(t.org.id)).resolves.not.toContain(t.userIds.viewer);
    await notificationService.notify(t.org.id, "comment_created", [t.userIds.viewer], { title: "t", body: "b", href: "/", actorId: null });
    await expect(notificationService.listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: t.userIds.viewer, limit: 10, cursor: null, unreadOnly: false } as never)).resolves.toMatchObject({ items: [] });
    void emit; void rateLimitState;
  });
});

